test('safe inline code uses a delimiter longer than any selected run and preserves padding',()=>{
  const source=tick.repeat(3)+' @{hidden} '+tick,delimiter=markdownCodeDelimiter(source);assert.equal(delimiter,tick.repeat(4));
  const result=markdownCommand(source,select(source),'code');assert.equal(result.value.slice(result.start,result.end),source);const parsed=analyzeMarkdown(result.value);assert.deepEqual(parsed.mentions,[]);assert.ok(parsed.html.includes('<code>'+source+'</code>'));
});
test('code fences preserve selected lines and cannot terminate on existing backticks or tildes',()=>{
  const source='@{hidden}\n'+tick.repeat(4)+'\n~~~~',result=markdownCommand('A '+source+' Z',{start:2,end:2+source.length},'fence');
  assert.equal(result.value.slice(result.start,result.end),source);assert.ok(result.value.includes(tick.repeat(5)+'\n'));assert.deepEqual(analyzeMarkdown(result.value).mentions,[]);assert.ok(result.value.endsWith('\n'+tick.repeat(5)+'\n Z'));
});
test('line commands preserve text selection while numbering multi-line and trailing-boundary ranges',()=>{
  const source='alpha\nbeta\ngamma',result=markdownCommand(source,{start:0,end:11},'ordered');assert.equal(result.value,'1. alpha\n2. beta\ngamma');assert.equal(result.start,3);assert.equal(result.end,17);
  const plain=markdownCommand(result.value,result,'ordered');assert.equal(plain.value,source);assert.equal(plain.start,0);assert.equal(plain.end,11);
});
test('headings quote bullet and task commands replace compatible prefixes and remain reversible',()=>{
  const heading=markdownCommand('Title',select('Title'),'heading:3');assert.equal(heading.value,'### Title');assert.equal(markdownCommand(heading.value,heading,'heading:3').value,'Title');
  const quote=markdownCommand('- item',select('- item'),'quote');assert.equal(quote.value,'> - item');
  const task=markdownCommand('3. task',select('3. task'),'task');assert.equal(task.value,'- [ ] task');assert.equal(markdownCommand(task.value,task,'bullet').value,'- task');
});
test('link serialization escapes label and destination delimiters and validates the canonical URL policy',()=>{
  const source='[Label]',linked=markdownCommand(source,select(source),'link',{url:'https://example.test/a(b)'});assert.equal(linked.value,'[\\[Label\\]](https://example.test/a\\(b\\))');assert.equal(linked.value.slice(linked.start,linked.end),'\\[Label\\]');assert.ok(analyzeMarkdown(linked.value).html.includes('href="https://example.test/a(b)"'));
  for(const url of ['javascript:alert(1)','data:text/html,<script>','https:\n//evil'])assert.throws(()=>markdownCommand(source,select(source),'link',{url}),/complete http/);
});
test('unsupported commands invalid headings and maximum length leave source untouched',()=>{
  assert.throws(()=>markdownCommand('text',select('text'),'unknown'),/Unknown/);assert.throws(()=>markdownCommand('text',select('text'),'heading:9'),/level/);assert.throws(()=>markdownCommand('text',select('text'),'bold',{maxLength:5}),/length/);
  assert.deepEqual(markdownSelection('abc',{start:99,end:-5,direction:'backward'}),{start:0,end:3,direction:'backward'});
});
test('keyboard shortcuts honor platform modifiers and preserve unrelated or composing keys',()=>{
  assert.equal(markdownShortcut({key:'B',ctrlKey:true}),'bold');assert.equal(markdownShortcut({key:'k',metaKey:true}),'link');assert.equal(markdownShortcut({key:'2',ctrlKey:true,altKey:true}),'heading:2');assert.equal(markdownShortcut({key:'&',code:'Digit7',metaKey:true,shiftKey:true}),'ordered');
  assert.equal(markdownShortcut({key:'b'}),null);assert.equal(markdownShortcut({key:'r',ctrlKey:true}),null);assert.equal(markdownShortcut({key:'b',ctrlKey:true,isComposing:true}),null);
});
